// Construit le bulletin COMPLET de la semaine (réservé aux abonnés) : e-mail HTML + texte WhatsApp.
const lignes = $('Lire la semaine').all().map((i) => i.json).filter((r) => r.semaine);
if (!lignes.length) throw new Error('Aucune cotation en base : rien à envoyer.');

const d = lignes.at(-1);
const p = lignes.at(-2);
const fmt = (n) => Number(n).toFixed(2).replace('.', ',');
const v = p ? ((d.prix - p.prix) / p.prix) * 100 : null;
const vTexte = v === null ? 'première semaine suivie' : `${v >= 0 ? '+' : ''}${v.toFixed(1).replace('.', ',')} % sur une semaine`;
const marche = d.marches || 'Rungis';
// Le commentaire n'est utilisé que s'il porte sur la dernière semaine cotée.
const commentaire = d.cle_commentaire === d.cle ? String(d.commentaire ?? '').trim() : '';
const echapper = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Veille conformité (workflow 04). Tant qu'elle n'a jamais tourné, la rubrique n'apparaît pas.
const veille = $input.first()?.json ?? {};
const veilleActive = !veille.error && !!veille.veille_maj_le;
const alertes = veilleActive ? (veille.alertes_mangue ?? []) : [];
const autres = veilleActive ? Number(veille.autres_semaine ?? 0) : 0;
const DATE_FR = (iso) => { const [a, m, j] = String(iso).split('-'); return `${j}/${m}/${a}`; };
const ligneAlerte = (a) => `${DATE_FR(a.date_alerte)} · ${a.pays_nom || 'Afrique de l\'Ouest'} · ${a.titre}`;
const sansAlerte = "Aucune alerte enregistrée sur la mangue d'Afrique de l'Ouest ces 30 derniers jours (RASFF, interceptions relevées, LMR).";
const autresTexte = autres ? `Cette semaine, ${autres} autre(s) notification(s) RASFF sur des produits d'Afrique de l'Ouest (hors mangue).` : '';

const sujet = `Baromètre mangue ${d.semaine} : ${fmt(d.prix)} €/kg (${vTexte})`;

const tableau = lignes.slice(-6).reverse().map((r, i, inv) => {
  const prec = inv[i + 1];
  const e = prec ? ((r.prix - prec.prix) / prec.prix) * 100 : null;
  return `<tr><td style="padding:6px 10px;border-top:1px solid #dfe4dc">${r.semaine}</td>`
    + `<td style="padding:6px 10px;border-top:1px solid #dfe4dc;text-align:right">${fmt(r.prix)} €/kg</td>`
    + `<td style="padding:6px 10px;border-top:1px solid #dfe4dc;text-align:right;color:#5b6a61">${e === null ? '—' : `${e >= 0 ? '+' : ''}${e.toFixed(1).replace('.', ',')} %`}</td></tr>`;
}).join('');

const html = `<!doctype html><html lang="fr"><body style="margin:0;background:#f7f8f5;font-family:Arial,Helvetica,sans-serif;color:#0f1a14">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border:1px solid #dfe4dc;border-radius:16px">
<tr><td style="background:#146c43;color:#ffffff;padding:18px 24px;border-radius:16px 16px 0 0">
  <div style="font-size:12px;letter-spacing:1px;text-transform:uppercase;opacity:.8">Baromètre abonnés · semaine ${d.semaine.slice(1)}</div>
  <div style="font-size:20px;font-weight:bold;margin-top:4px">Mangue · prix grossiste · ${echapper(marche)}</div>
</td></tr>
<tr><td style="padding:24px">
  <div style="font-size:34px;font-weight:bold">${fmt(d.prix)} <span style="font-size:16px;color:#5b6a61">€/kg</span></div>
  <div style="margin-top:4px;font-weight:bold;color:${v !== null && v < 0 ? '#c2410c' : '#146c43'}">${vTexte}</div>
  ${commentaire ? `<div style="margin-top:20px;padding:16px;border-left:4px solid #e8900c;background:#fdecd0;border-radius:8px">
    <div style="font-size:12px;font-weight:bold;text-transform:uppercase;color:#5b6a61">Lecture de la semaine</div>
    <div style="margin-top:6px;font-size:16px;line-height:1.5">${echapper(commentaire)}</div></div>` : ''}
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:20px;font-size:14px">
    <tr><th align="left" style="padding:6px 10px;color:#5b6a61;font-weight:normal">Semaine</th><th align="right" style="padding:6px 10px;color:#5b6a61;font-weight:normal">Prix moyen</th><th align="right" style="padding:6px 10px;color:#5b6a61;font-weight:normal">Évolution</th></tr>
    ${tableau}
  </table>
  ${veilleActive ? `<div style="margin-top:20px;padding:16px;border:1px solid #dfe4dc;border-radius:8px">
    <div style="font-size:12px;font-weight:bold;text-transform:uppercase;color:#5b6a61">Conformité UE · mangue</div>
    ${alertes.length
      ? alertes.map((a) => `<div style="margin-top:8px;font-size:14px;line-height:1.5">${echapper(ligneAlerte(a))}${a.url ? ` · <a href="${echapper(a.url)}" style="color:#146c43">détail</a>` : ''}</div>`).join('')
      : `<div style="margin-top:8px;font-size:14px;line-height:1.5">${sansAlerte}</div>`}
    ${autresTexte ? `<div style="margin-top:8px;font-size:12px;color:#5b6a61">${autresTexte}</div>` : ''}
  </div>` : ''}
  <p style="margin-top:20px;font-size:12px;color:#5b6a61">Source : RNM FranceAgriMer, ${d.nb_cotations} cotation(s) cette semaine, dernière le ${d.derniere_date}. Commentaire rédigé par IA à partir de ces seuls chiffres.</p>
</td></tr>
<tr><td style="padding:16px 24px;border-top:1px solid #dfe4dc;font-size:12px;color:#5b6a61">
  Vous recevez ce bulletin car vous êtes abonné Premium. Merci de ne pas le transférer. Pour vous désabonner, répondez simplement à cet e-mail.
</td></tr></table></td></tr></table></body></html>`;

const texte = `${sujet}\n\n${commentaire}${veilleActive ? `\n\nConformité UE · mangue :\n${alertes.length ? alertes.map(ligneAlerte).join('\n') : sansAlerte}` : ''}\n\nSource : RNM FranceAgriMer. Pour vous désabonner, répondez à cet e-mail.`;

const whatsapp = [
  `*Baromètre mangue · ${d.semaine}*`,
  `${marche} : *${fmt(d.prix)} €/kg* (${vTexte})`,
  commentaire ? `\n${commentaire}` : '',
  veilleActive ? `\n*Conformité UE · mangue*\n${alertes.length ? alertes.map((a) => `• ${ligneAlerte(a)}`).join('\n') : sansAlerte}` : '',
  `\n_Réservé aux abonnés Premium, merci de ne pas transférer._`,
].filter(Boolean).join('\n');

return [{ json: { semaine: d.semaine, sujet, html, texte, whatsapp, commentaire_present: !!commentaire } }];

// RÉGLAGES : à adapter une fois.
// Sans domaine vérifié sur Resend, seule l'adresse « onboarding@resend.dev » marche, et uniquement vers
// l'e-mail de votre compte Resend : parfait pour tester. Ensuite, vérifiez un domaine sur resend.com/domains.
const EXPEDITEUR = 'Baromètre IE <onboarding@resend.dev>';
const ADMIN = 'a-remplacer@exemple.com'; // votre e-mail : reçoit le message WhatsApp prêt à copier
const REPONSE_A = ADMIN; // les réponses des abonnés (désabonnement, question à l'analyste) arrivent ici

const b = $('Préparer le bulletin').first().json;
const abonnes = $input.all().map((i) => i.json).filter((a) => a.email);

const sorties = [];
// Resend accepte 100 e-mails par appel « batch » : un e-mail par abonné, personne ne voit les autres adresses.
for (let i = 0; i < abonnes.length; i += 100) {
  sorties.push({ json: {
    chemin: 'emails/batch',
    corps: abonnes.slice(i, i + 100).map((a) => ({
      from: EXPEDITEUR, to: [a.email], reply_to: REPONSE_A, subject: b.sujet, html: b.html, text: b.texte,
    })),
  } });
}

// Copie pour vous : le message WhatsApp à coller dans le groupe privé des abonnés.
sorties.push({ json: {
  chemin: 'emails',
  corps: {
    from: EXPEDITEUR,
    to: [ADMIN],
    subject: `[À coller dans WhatsApp] ${b.sujet}`,
    text: `Bulletin envoyé par e-mail à ${abonnes.length} abonné(s).`
      + (b.commentaire_present ? '' : '\nAttention : pas de commentaire IA pour cette semaine.')
      + `\n\nMessage WhatsApp à copier :\n\n${b.whatsapp}`,
  },
} });
return sorties;
